    if n == 1:
        return matrix[0][0]
    # Use recursive Laplace expansion on the first row.
    def det(mat):
        size = len(mat)
        if size == 1:
            return mat[0][0]
        if size == 2:
            return mat[0][0]*mat[1][1] - mat[0][1]*mat[1][0]
        total = 0
        sign = 1
        for col in range(size):
            element = mat[0][col]
            if element != 0:
                # Build submatrix excluding row 0 and column col
