def solve(coins, amount):
    # Edge case
    if amount < 0:
        return -1
    # DP array where dp[i] = min coins to make i, init large
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                if dp[i - c] + 1 < dp[i]:
                    dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] != amount + 1 else -1

