def solve(path: str) -> str:
    # Split by slash and process components using a stack.
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Empty component (due to //) or current directory - ignore.
            continue
        if part == '..':
            # Go up one directory if possible.
            if stack:
                stack.pop()
            # If stack empty we are at root, stay there.
        else:
            # Normal directory name.
            stack.append(part)
    # Build the canonical path.
    result = '/' + '/'.join(stack)
    # Ensure root is represented as '/' (join of empty list gives empty string).
    return result if result != '' else '/'

