import random, math

def solve(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    A = [row[:] for row in matrix]
    det_sign = 1
    for k in range(n-1):
        if A[k][k] == 0:
            swap = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            A[k], A[swap] = A[swap], A[k]
            det_sign = -det_sign
        for i in range(k+1, n):
            for j in range(k+1, n):
                prev = A[k-1][k-1] if k>0 else 1
                A[i][j] = (A[k][k] * A[i][j] - A[i][k] * A[k][j]) // prev
        for i in range(k+1, n):
            A[i][k] = 0
    return det_sign * A[n-1][n-1]

def det_bruteforce(m):
    # compute using recursion
    n=len(m)
    if n==0:
        return 1
    if n==1:
        return m[0][0]
    def rec(mat):
        size=len(mat)
        if size==1:
            return mat[0][0]
        if size==2:
            return mat[0][0]*mat[1][1]-mat[0][1]*mat[1][0]
        total=0
        sign=1
        for col in range(size):
            sub=[row[:col]+row[col+1:] for row in mat[1:]]
            total+=sign*mat[0][col]*rec(sub)
            sign=-sign
        return total
    return rec(m)

for _ in range(200):
    n=random.randint(0,5)
    mat=[[random.randint(-5,5) for _ in range(n)] for __ in range(n)]
    if solve(mat)!=det_bruteforce(mat):
        print('mismatch', mat, solve(mat), det_bruteforce(mat))
        break
else:
    print('all good')

