def solve(meetings):
    """Return the maximum number of non-overlapping meetings.
    Each meeting is a pair (start, end). If start > end, the interval is normalized
    by swapping the values. Meetings may share endpoints.
    """
    if not meetings:
        return 0
    normalized = []
    for m in meetings:
        if not isinstance(m, (list, tuple)) or len(m) < 2:
            continue
        s, e = m[0], m[1]
        # Ensure comparable numbers; skip if not numeric
        try:
            s + e  # type check
        except Exception:
            continue
        if s > e:
            s, e = e, s
        normalized.append((s, e))
    # Sort by end time then start
    normalized.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for s, e in normalized:
        if s >= last_end:
            count += 1
            last_end = e
    return count

