def solve(path: str) -> str:
    """Simplify an absolute Unix file path.
    Rules:
    - '.' means current directory and is ignored.
    - '..' moves up one directory (pop the stack if possible).
    - Multiple slashes are treated as a single separator.
    - The result is an absolute path starting with '/', with no trailing slash unless it is the root.
    """
    # Split by '/' and process components
    parts = path.split('/')
    stack = []
    for part in parts:
        if not part or part == '.':
            # Skip empty parts (caused by leading, trailing, or multiple slashes) and '.'
            continue
        if part == '..':
            if stack:
                stack.pop()
            # If stack empty, we stay at root
        else:
            stack.append(part)
    # Join the stack to form the simplified path
    return '/' + '/'.join(stack)

