{"task_id": "T35", "code": "def solve(grid):
    """Count the number of islands (connected components of 1s) in a binary grid.
    Connectivity is 4-directional (up, down, left, right). The grid may be empty or have rows of differing lengths.
    """
    if not grid:
        return 0
    rows = len(grid)
    # Use a set for visited cells to handle irregular shapes
    visited = set()
    def neighbors(r, c):
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows:
                # check column bounds for this neighbor row
                if 0 <= nc < len(grid[nr]):
                    yield nr, nc
    def dfs(start_r, start_c):
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            if grid[r][c] != 1:
                continue
            visited.add((r, c))
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] == 1:
                    stack.append((nr, nc))
    count = 0
    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 1 and (r, c) not in visited:
                dfs(r, c)
                count += 1
    return count"}

