def solve(grid):
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def neighbors(r,c):
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                yield nr,nc
    def dfs(r,c):
        stack=[(r,c)]
        while stack:
            x,y=stack.pop()
            if (x,y) in visited or grid[x][y]!=1:
                continue
            visited.add((x,y))
            for nr,nc in neighbors(x,y):
                if (nr,nc) not in visited and grid[nr][nc]==1:
                    stack.append((nr,nc))
    count=0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j]==1 and (i,j) not in visited:
                dfs(i,j)
                count+=1
